sub:Head {
  this: a np:Nanopublication ;
    np:hasAssertion sub:assertion ;
    np:hasProvenance sub:provenance ;
    np:hasPublicationInfo sub:pubinfo .
}

sub:assertion {
  <https://w3id.org/delphi/resource/claim/real-organisms-score-plausible-is-near-worthless> a delphi:Claim ;
    rdfs:label "A high share of real held-out organisms scoring plausible says almost nothing about whether the design scorer works, because negatives score plausible too." ;
    dct:description "Status: a reported observation from one blind, family-out held-out run of every scorer version, as written in sim-engine/validate/evaluation/SCORER-EVALUATION.md (lines 14, 45, 46, 47); this draft restates the document and did not re-run or independently re-verify it. The document reports that nearly all real held-out organisms clear the 0.5 plausibility cut while only a small minority of negatives fall below it, so the cut barely separates the two groups. What this does NOT establish: it does not show that any scorer version is useless or that none discriminates, because it concerns only the share of real organisms above the cut and not any ranking or separation measure; it does not say which version is best; and the few low-scoring families (sim-engine/validate/evaluation/SCORER-EVALUATION.md:183, :186) are illustrations, not an explanation of the weakness." ;
    delphi:hasEvidence <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> .

  <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> a delphi:EvidenceItem ;
    rdfs:label "Real held-out organisms nearly all pass the 0.5 plausibility cut, yet most negatives pass it as well" ;
    dct:description "Evidence summarised from sim-engine/validate/evaluation/SCORER-EVALUATION.md: the run covers 168 held-out families scored family-out (line 14); 98 to 99.6 % of real organisms score at or above 0.5 in every version (line 45); only 12 to 17 % of negatives score below 0.5 (line 46); the document concludes every version is close to calling everything plausible (line 47). Per-family exceptions are at lines 183 and 186." ;
    schema:additionalProperty sub:pv-families, sub:pv-real-low, sub:pv-real-high, sub:pv-cut, sub:pv-neg-low, sub:pv-neg-high, sub:pv-threshold, sub:pv-eury, sub:pv-eury-total, sub:pv-aspred, sub:pv-aspred-total, sub:pv-minimum-items, sub:pv-score, sub:pv-distance .

  sub:pv-families a schema:PropertyValue ;
    schema:propertyID "heldOutFamilyCount" ;
    schema:value 168 ;
    schema:description "Held-out families scored family-out in the blind run of every scorer version (SCORER-EVALUATION.md:14)." .

  sub:pv-real-low a schema:PropertyValue ;
    schema:propertyID "realOrganismsAtOrAboveCutLowestPercent" ;
    schema:value 98 ;
    schema:description "Lowest percentage, across versions, of real held-out organisms scoring at or above the cut (SCORER-EVALUATION.md:45)." .

  sub:pv-real-high a schema:PropertyValue ;
    schema:propertyID "realOrganismsAtOrAboveCutHighestPercent" ;
    schema:value 99.6 ;
    schema:description "Highest percentage, across versions, of real held-out organisms scoring at or above the cut (SCORER-EVALUATION.md:45)." .

  sub:pv-cut a schema:PropertyValue ;
    schema:propertyID "plausibilityCut" ;
    schema:value 0.5 ;
    schema:description "Plausibility score cut used for both real organisms and negatives (SCORER-EVALUATION.md:45, :46)." .

  sub:pv-neg-low a schema:PropertyValue ;
    schema:propertyID "negativesBelowCutLowestPercent" ;
    schema:value 12 ;
    schema:description "Lowest percentage of negatives scoring below the cut (SCORER-EVALUATION.md:46)." .

  sub:pv-neg-high a schema:PropertyValue ;
    schema:propertyID "negativesBelowCutHighestPercent" ;
    schema:value 17 ;
    schema:description "Highest percentage of negatives scoring below the cut (SCORER-EVALUATION.md:46)." .

  sub:pv-threshold a schema:PropertyValue ;
    schema:propertyID "familyPlausibleShareThresholdPercent" ;
    schema:value 80 ;
    schema:description "Share of a family's real items scoring plausible below which a family is listed as low (SCORER-EVALUATION.md:183)." .

  sub:pv-minimum-items a schema:PropertyValue ;
    schema:propertyID "minimumRealItemsPerListedFamily" ;
    schema:value 3 ;
    schema:description "Minimum number of real items a family needs to be listed in the low-family check (SCORER-EVALUATION.md:183)." .

  sub:pv-eury a schema:PropertyValue ;
    schema:propertyID "eurypharyngidaePlausibleCount" ;
    schema:value 3 ;
    schema:description "Gulper eels (Eurypharyngidae) scoring plausible: 3 of 5 (SCORER-EVALUATION.md:183)." .

  sub:pv-eury-total a schema:PropertyValue ;
    schema:propertyID "eurypharyngidaeRealItemCount" ;
    schema:value 5 ;
    schema:description "Real items in Eurypharyngidae (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred a schema:PropertyValue ;
    schema:propertyID "aspredinidaePlausibleCount" ;
    schema:value 20 ;
    schema:description "Banjo catfishes (Aspredinidae) scoring plausible: 20 of 29 (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred-total a schema:PropertyValue ;
    schema:propertyID "aspredinidaeRealItemCount" ;
    schema:value 29 ;
    schema:description "Real items in Aspredinidae (SCORER-EVALUATION.md:183)." .

  sub:pv-score a schema:PropertyValue ;
    schema:propertyID "fs-05942Score" ;
    schema:value 0.15 ;
    schema:description "Plausibility score of the gulper eel fs-05942, an example low scorer (SCORER-EVALUATION.md:186)." .

  sub:pv-distance a schema:PropertyValue ;
    schema:propertyID "fs-05942NearestNeighbourDistance" ;
    schema:value 0.96 ;
    schema:description "Distance from fs-05942 to its nearest remaining neighbour, the cutlassfish Lepturacanthus savala, once its family is removed (SCORER-EVALUATION.md:186)." .
}

